import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.MultilineRecursiveToStringStyle;
import org.apache.commons.lang3.builder.ReflectionToStringBuilder;

public class Probe {
    static class Job { String title; }
    static class Person { String name; int age; boolean smoker; Job job; }

    public static void main(String[] args) {
        Integer base = Integer.valueOf(5);
        String baseStr = base.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(base));
        MultilineRecursiveToStringStyle style = new MultilineRecursiveToStringStyle();

        System.out.println("BLANK=[" + new ToStringBuilder(base, style).toString() + "]");
        System.out.println("expectedPrefix=" + baseStr);

        System.out.println("LONG=[" + new ToStringBuilder(base, style).append("a", 3L).toString() + "]");

        long[] arr = new long[] {1, 2, -3, 4};
        System.out.println("LONGARR=[" + new ToStringBuilder(base, style).append(arr).toString() + "]");

        long[][] arr2 = new long[][] {{1,2}, null, {5}};
        System.out.println("LONGARR2=[" + new ToStringBuilder(base, style).append(arr2).toString() + "]");

        Object[] oarr = new Object[] {null, base, new int[]{3,6}};
        System.out.println("OBJARR=[" + new ToStringBuilder(base, style).append(oarr).toString() + "]");

        Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        ReflectionToStringBuilder builder = new ReflectionToStringBuilder(p, style);
        System.out.println("PERSON=[" + builder.toString() + "]");
        System.out.println("forceAccessible=" + builder.isForceAccessible());

        System.out.println("NULLOBJ=[" + new ToStringBuilder(base, style).append((Object) null).toString() + "]");
        System.out.println("NAMEDNULL=[" + new ToStringBuilder(base, style).append("a", (Object) null).toString() + "]");

        java.util.ArrayList<Object> emptyList = new java.util.ArrayList<Object>();
        System.out.println("EMPTYLISTNODETAIL=[" + new ToStringBuilder(base, style).append("a", emptyList, false).toString() + "]");
        System.out.println("EMPTYLISTDETAIL=[" + new ToStringBuilder(base, style).append("a", emptyList, true).toString() + "]");

        boolean[] barr = new boolean[] {true, false, true};
        System.out.println("BOOLARR=[" + new ToStringBuilder(base, style).append(barr).toString() + "]");

        System.out.println("APPENDSUPER=[" + new ToStringBuilder(base, style).appendSuper("Integer@8888[]").append("a","hello").toString() + "]");
    }
}
